        Fill(0,0,32,16,160,105,80);Fill(8,8,8,8,225,177,135);for(int x=8;x<16;x++)Fill(x,8,1,2,70,55,45);Fill(9,11,2,1,80,180,220);Fill(13,11,2,1,80,180,220);Fill(40,8,1,1,0,0,255);Fill(16,16,24,16,30,95,145);Fill(20,20,8,12,40,150,180);Fill(0,16,16,16,45,50,80);Fill(40,16,16,16,130,175,190);if(height==64){Fill(16,48,16,16,45,50,80);Fill(32,48,16,16,130,175,190);}var bitmap=BitmapSource.Create(64,height,96,96,PixelFormats.Bgra32,null,pixels,256);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var output=new MemoryStream();encoder.Save(output);return output.ToArray();
    }
